CUresult cuDriverGetVersion(int * driverVersion) {
    // TraceCall("cuDriverGetVersion");
    CUresult res = CUDA_SUCCESS;

    if (!driverVersion) {
        res = CUDA_ERROR_INVALID_VALUE;
    }

    if (res == CUDA_SUCCESS) {
        *driverVersion = CUDA_VERSION;
    }

    return res;
}

CUresult cuGetProcAddress(const char * symbol, void ** pfn, int cudaVersion, cuuint64_t flags) {
    // TraceCall("cuGetProcAddress");
    if (cudaVersion > 12010) { return (CUresult)1; }

    if (!initialize() || g_interface.hgGetProcAddress_ptr == NULL) {
        fprintf(stderr, "Initialize HGGC Api Failed: hgGetProcAddress.\n");
        exit(1);
    }

#define MAX_SYMBOL_SIZE 128
    char new_symbol[MAX_SYMBOL_SIZE] = {0};

    const char *old_patterns[] = {"cuuint32_t", "cuuint64_t", "NvSci", "cuda", "CUDA", "cu", "CU", "nv"};
    const char *new_patterns[] = {"uint32_t", "uint64_t", "HgSci", "hggc", "HGGC", "hg", "HG", "hg"};
    const int rule_count = 8;

    size_t src_idx = 0;
    size_t dst_idx = 0;

    while (symbol[src_idx] != '\0') {
      bool matched = false;
      for (int i = 0; i < rule_count; i++) {
        size_t old_len = strlen(old_patterns[i]);
        size_t new_len = strlen(new_patterns[i]);
        if (strncmp(&symbol[src_idx], old_patterns[i], old_len) == 0) {
          bool hit = false;
          char c1 = old_patterns[i][0];
          char c2 = old_patterns[i][old_len - 1];
          if (src_idx == 0) {
            char after_c2 = symbol[src_idx + old_len];
            hit = (!!isupper(c2) != !!isupper(after_c2));
          } else if (src_idx == (strlen(symbol) - old_len)) {
            char before_c1 = symbol[src_idx - 1];
            hit = (!!isupper(c1) != !!isupper(before_c1));
          } else {
            char before_c1 = symbol[src_idx - 1];
            char after_c2 = symbol[src_idx + old_len];
            bool opposite1 = (!!isupper(c1) != !!isupper(before_c1));
            bool opposite2 = (!!isupper(c2) != !!isupper(after_c2));
            hit = opposite1 && opposite2;
          }
          if ((dst_idx + new_len < MAX_SYMBOL_SIZE) && hit) {
            memcpy(&new_symbol[dst_idx], new_patterns[i], new_len);
            dst_idx += new_len;
            src_idx += old_len;
            matched = true;
            break;
          }
        }
      }
      if (!matched) {
        if (dst_idx + 1 < MAX_SYMBOL_SIZE) {
          new_symbol[dst_idx++] = symbol[src_idx++];
        } else {
          break;
        }
      }
    }

    new_symbol[dst_idx] = '\0';

    bool needProfile = g_profileHandler.isCallbackEnabled != NULL &&
        g_profileHandler.isCallbackEnabled(g_profileDomain, cuda_TRACE_CBID_cuGetProcAddress) != 0;
    if (needProfile) {
        g_profileHandler.profileCallbackBegin(g_profileDomain, cuda_TRACE_CBID_cuGetProcAddress);
    }

    auto __ret = g_interface.hgGetProcAddress_ptr((const char * )new_symbol, (void ** )pfn, (int)cudaVersion, (uint64_t)flags);

    if (needProfile) {
        g_profileHandler.profileCallbackEnd(g_profileDomain, cuda_TRACE_CBID_cuGetProcAddress);
    }

    return (CUresult)__ret;
}

